<?php
declare(strict_types=1);
require_once __DIR__.'/contract-details.php';
function ct_dispatch(array $a,string $route,string $method):never{
 cc_owner($a);ct_gate();
 if($method==='GET'){
  if($route==='settings'){$order=isset($_GET['order'])?filter_var($_GET['order'],FILTER_VALIDATE_INT):null;if($order!==null)crm_record('orders',cc_id($order));$where=$order?' WHERE order_id=?':'';$params=$order?[$order]:[];$owner=crm_query('SELECT * FROM nd_lc_owner_profiles ORDER BY id DESC LIMIT 1')->fetch();$details=crm_query('SELECT * FROM nd_lc_customer_details'.$where.' ORDER BY id DESC LIMIT 100',$params)->fetchAll();$terms=crm_query('SELECT * FROM nd_lc_contract_terms'.$where.' ORDER BY id DESC LIMIT 100',$params)->fetchAll();json_response(['ok'=>true,'owner'=>$owner,'owner_labels'=>ct_owner_labels(),'owner_defaults'=>['full_name'=>'Сухарева Наталья Владимировна','status'=>'npd','email'=>'admin@neurodelo.pro','postal_address'=>'Романово, Калининградская область','max'=>'https://max.ru/u/f9LHodD0cOKgQK_L9u-un2-ttcwfRfu_-_a-2Ai_usx_frNtjq1jjuiZSLE','telegram'=>'https://t.me/minden2006'],'details'=>$details,'terms'=>$terms,'template_fields'=>array_column(ct_catalog(),'fields','kind'),'package_template_ids'=>array_values(array_map(static fn($t)=>(int)$t['id'],array_filter(crm_query('SELECT id,clauses_json FROM nd_lc_templates ORDER BY id DESC LIMIT 200')->fetchAll(),static fn($t)=>isset(json_decode($t['clauses_json'],true)['_package']))))]);}
  if(preg_match('~^source/([1-9][0-9]*)$~D',$route,$m)){$t=lc_template((int)$m[1]);$item=$t['clauses']['_package']??null;if(!$item)crm_fail(404,'Нет отдельного исходника.');foreach(ct_catalog() as $source)if($source['sha256']===$item['sha256']){$path=__DIR__.'/package/'.$source['file'];if(hash_file('sha256',$path)!==$source['sha256'])crm_fail(503,'Исходник повреждён.');header('Content-Type: application/vnd.openxmlformats-officedocument.wordprocessingml.document');header('Content-Disposition: attachment; filename="'.$source['file'].'"');header('Cache-Control: private, no-store');readfile($path);exit;}foreach(['01_contract-r1.docx','02_specification-r1.docx'] as $name){$path=__DIR__.'/package/history/'.$name;if(is_file($path)&&hash_file('sha256',$path)===$item['sha256']){header('Content-Type: application/vnd.openxmlformats-officedocument.wordprocessingml.document');header('Content-Disposition: attachment; filename="'.$name.'"');header('Cache-Control: private, no-store');readfile($path);exit;}}crm_fail(404,'Исходник не найден.');}
  if(preg_match('~^sample/([1-9][0-9]*|agreement|specification)$~D',$route,$m)){$t=ct_preview_template($m[1]);$item=$t['clauses']['_package']??null;if(!$item||$item['kind']!==$t['kind'])crm_fail(409,'Содержимое не соответствует типу шаблона.');$bytes=ct_sample_preview($t);header('Content-Type: application/pdf');header('Content-Disposition: attachment; filename="NeuroDelo-'.$t['kind'].'-v'.$t['revision_number'].'-sample.pdf"');header('X-Neuro-Template-Kind: '.$t['kind']);header('X-Neuro-Template-Id: '.$t['id']);header('X-Neuro-Template-Checksum: '.$t['checksum']);header('X-Neuro-PDF-SHA256: '.hash('sha256',$bytes));header('Cache-Control: private, no-store');header('Pragma: no-cache');header('Expires: 0');header('Vary: Cookie');echo $bytes;exit;}

 }
 if($method==='POST'){$d=input();$r=lc_mutation($a,'contracts/'.$route,$d,function()use($a,$route,$d){
  if($route==='import')return ct_import($a);if($route==='owner')return ct_owner_save($d);if($route==='review')return ct_review_details($d);if($route==='terms')return ct_terms_save($d);if($route==='generate')return ct_generate($a,$d);if($route==='generate-pair')return ct_generate_pair($a,$d);
  if(in_array($route,['review-pdf','completed-copy','release-payment'],true)){$b=lc_binding($a,cc_id($d['binding_id']??null),true);$asset=ct_asset($b);cc_file_path($asset);if(($d['confirm']??false)!==true)crm_fail(422,'Подтвердите просмотр точной версии.');$reason=cc_text($d,'reason',3000);
   if($route==='review-pdf'){if(($d['pdf_checksum']??'')!==$asset['checksum']||$b['state']!=='OWNER_REVIEW')crm_fail(409,'Проверьте точный PDF перед выдачей.');crm_query('UPDATE nd_lc_pdf_assets SET owner_reviewed_at=UTC_TIMESTAMP() WHERE binding_id=?',[$b['id']]);}
   if($route==='completed-copy'){if($b['state']!=='AGREED')crm_fail(409,'Сначала отдельно проверьте подписи заказчика.');$f=cc_file($a,cc_id($d['file_id']??null));if((int)$f['project_id']!==(int)$b['project_id']||$f['actor_type']!=='owner'||$f['visibility']!=='customer'||!in_array($f['mime'],['application/pdf','image/jpeg','image/png'],true))crm_fail(422,'Нужна частная копия этого проекта, загруженная владельцем.');cc_file_path($f);if($asset['copy_released_at']!==null)crm_fail(409,'Завершённая копия уже выпущена. Создайте новую редакцию, сохранив историю.');crm_query('UPDATE nd_lc_pdf_assets SET countersigned_file_id=?,copy_review_reason=?,copy_released_at=UTC_TIMESTAMP() WHERE binding_id=?',[$f['id'],$reason,$b['id']]);}
   if($route==='release-payment'){if($b['kind']!=='agreement'||$b['state']!=='AGREED'||!$asset['copy_released_at'])crm_fail(409,'Сначала проверьте и передайте завершённую копию договора.');lc_schedule_activate($a,(int)$b['id'],$d);crm_query('UPDATE nd_lc_pdf_assets SET payment_released_at=COALESCE(payment_released_at,UTC_TIMESTAMP()) WHERE binding_id=?',[$b['id']]);}
   lc_audit($a,'document',(int)$b['id'],$route,(int)$b['version'],['reason'=>$reason,'pdf_sha256'=>$asset['checksum']]);return ['ok'=>true,'id'=>(int)$b['id']];
  }crm_fail(404,'Действие не найдено.');});json_response($r);
 }crm_fail(404,'Раздел не найден.');
}
